-- Catálogo de productos para la demo de búsqueda (ADI, apps web en móviles)
-- Datos FICTICIOS generados automáticamente: las marcas no son reales.
-- Ejecutar en el SQL Editor de Supabase. No toca la tabla `lista`.

create table if not exists public.catalogo (
  id          bigint generated always as identity primary key,
  nombre      text not null,
  marca       text,
  formato     text,
  categoria   text,
  descripcion text
);

alter table public.catalogo enable row level security;

drop policy if exists "Catálogo visible para usuarios autenticados" on public.catalogo;
create policy "Catálogo visible para usuarios autenticados"
  on public.catalogo for select
  to authenticated
  using (true);

-- Opcional: índice para búsquedas con ilike '%texto%' (con unos miles de filas no hace falta)
-- create extension if not exists pg_trgm;
-- create index if not exists catalogo_nombre_trgm on public.catalogo using gin (nombre gin_trgm_ops);

truncate public.catalogo restart identity;





